<script>
    // --- DOM Elements ---
    const header = document.getElementById('header');
    const hamburger = document.getElementById('hamburger');
    const navLinks = document.getElementById('navLinks');
    const tabBtns = document.querySelectorAll('.tab-btn');
    const tabPanels = document.querySelectorAll('[role="tabpanel"]');
    const revealElements = document.querySelectorAll('.reveal');

    // --- 1. Header Scroll Effect ---
    window.addEventListener('scroll', () => {
        if (window.scrollY > 50) header.classList.add('scrolled');
        else header.classList.remove('scrolled');
    });

    // --- 2. Mobile Menu Toggle ---
    hamburger.addEventListener('click', () => {
        hamburger.classList.toggle('active');
        navLinks.classList.toggle('active');
        document.body.style.overflow = navLinks.classList.contains('active') ? 'hidden' : '';
    });

    // Close mobile menu on link click
    navLinks.querySelectorAll('a').forEach(link => {
        link.addEventListener('click', () => {
            hamburger.classList.remove('active');
            navLinks.classList.remove('active');
            document.body.style.overflow = '';
        });
    });

    // --- 3. Menu Tab Switching ---
    tabBtns.forEach(btn => {
        btn.addEventListener('click', () => {
            // Update Buttons
            tabBtns.forEach(b => b.classList.remove('active'));
            btn.classList.add('active');

            // Update Panels
            const targetId = btn.dataset.tab;
            tabPanels.forEach(panel => {
                if (panel.id === `tab-${targetId}`) {
                    panel.hidden = false;
                    // Re-trigger animation for new items
                    panel.querySelectorAll('.menu-item').forEach((item, i) => {
                        item.style.transitionDelay = `${i * 100}ms`;
                        item.classList.remove('visible');
                        // Force reflow
                        void item.offsetWidth;
                        item.classList.add('visible');
                    });
                } else {
                    panel.hidden = true;
                }
            });
        });
    });

    // --- 4. Intersection Observer for Scroll Animations ---
    const observerOptions = { root: null, threshold: 0.1, rootMargin: '0px 0px -50px 0px' };
    const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                entry.target.classList.add('active');
                observer.unobserve(entry.target); // Animate once
            }
        });
    }, observerOptions);

    revealElements.forEach(el => observer.observe(el));

    // --- 5. Initial Menu Item Animation Trigger ---
    // Run once on load for the default active tab
    document.querySelectorAll('#tab-espresso .menu-item').forEach((item, i) => {
        item.style.transitionDelay = `${i * 100}ms`;
        setTimeout(() => item.classList.add('visible'), 300 + i * 100);
    });

    // --- 6. Smooth Focus Styles for Accessibility ---
    document.addEventListener('keydown', (e) => {
        if (e.key === 'Tab') document.body.classList.add('keyboard-nav');
    });
    document.addEventListener('mousedown', () => document.body.classList.remove('keyboard-nav'));
</script>
